local function update_ds_pay_url_base()
    local _env = get_env()

    if _env == M.ENV.DEBUG then
        current_url_base = URL_BASE.DEBUG
    else
        current_url_base = URL_BASE.RELEASE
    end

    UP.set_url_base_with_type(UP.SERVICE_TYPE.DS_PAY, current_url_base)
end

-- 环境
function M.set_env(_env)
    E.LOG.debug(TAG, "set_env: " .. tostring(_env))
    l_env = _env

    update_ds_pay_url_base()
end

function M.check_products()
    EG.product_infos_base(CHANNEL, function(succ, infos)
        products_request_times = products_request_times + 1
        if succ then
            E.LOG.debug(TAG, "获取 aligames product info success >>")

            product_infos = infos
            ET.publish('purchase_inited', CHANNEL)

            E.LOG.debug(TAG, product_infos)

            pay_inited = true

            local stat_params = {}
            stat_params.request_times = products_request_times
            ESTAT.stat_action('products_check', nil, true, stat_params)
        else
            E.LOG.debug(TAG,"获取 aligames product info failure")

            local user_info = EG.user_info()
            if user_info ~= nil and next(user_info) ~= nil then
                E.LOG.debug(TAG, "it's login state, and need recheck products")
                E.Timer.once(5, M.check_products)

                if products_request_times == 50 then
                    E.LOG.warn(TAG, "check_products reaches so much times, need stat")
                    local stat_params = {}
                    stat_params.request_times = products_request_times
                    ESTAT.stat_action('products_check', nil, false, stat_params)
                end
            else
                E.LOG.debug(TAG, "check_products logout state, not need check products")
            end
        end
    end)
end

local login_handler = function()
    -- 已经初始化了pay，不需再次执行
    if pay_inited then
        return
    end

    E.LOG.debug(TAG,"开始获取 aligames product info")

    -- 重置商品列表请求次数
    products_request_times = 0
    M.check_products()
end

function M.init(opt, cb)
    E.LOG.debug(TAG, "init begin")
    pay_listener = opt.pay_listener

    if initted then
        E.LOG.debug(TAG, "already initted, and return")
        if cb then
            cb(true)
        end
        return
    end

    -- 更新ds pay url base
    update_ds_pay_url_base()

    initted = M.uni_init()
    ET.subscribe(ET.gangplank.LOGIN, login_handler)

    if cb then
        cb(initted)
    end
end

function M.uni_init()
    if initted then
        E.LOG.debug(TAG, "already initted, and return")
        return true
    end

    E.LOG.debug(TAG, "init begin with url_base:" .. tostring(current_url_base))
    -- http://dspay.alibaba.net/ejoyclient/gwpc.order.create?ver=1.0&df=json&cver=3.8.3&os=windows
    UP.set_url_base_with_type(UP.SERVICE_TYPE.DS_PAY, current_url_base)

    initted = true
    return initted
end

-- 当前只支持灵犀渠道
local function check_platform_support()
    local user_info = EG.user_info() or {}
    local current_platform = user_info.platform

    local valid = _ejoysdk.os and _ejoysdk.os() == "windows"
            and current_platform == LX_PLATFORM

    E.LOG.debug(TAG, "check_platform_valid result:" .. tostring(valid) .. ", current_platform:" .. tostring(current_platform))
    return valid
end

local function create_order(_ejoy_order_id, pay_params, cb)
    local params = {}
    local user_info = EG.user_info() or {}

    -- params参数参考：https://yuque.antfin-inc.com/ejoy-platform/ejoy-platform/hadm8b

    params.token = user_info.ptoken
    -- 商品信息
    params.cpOrderId = pay_params.cpOrderId
    params.amount = pay_params.amount
    params.productInfo = {
        productId = pay_params.payProductID,
        productName = pay_params.payProductName,
        productDetail = pay_params.payProductDescribe
    }
    params.callbackUrl = pay_params.payCallbackURL
    params.cpOrderParam = pay_params.payCallbackParams

    -- 0-渠道支付；1-自有支付 （非必填）
    params.payType = PAY_TYPE.PAY_TYPE_INNER
    -- pc 来自PC客户端
    params.orderSrc = ORDER_SRC_WIN

    --角色信息
    local player_info = EG.player_info() or {}
    params.roleInfo = {
        roleId = player_info.player_id,
        roleName = player_info.player_name,
        serverId = player_info.server_id
    }

    UP.post(UP.SERVICE.GWPC_ORDER_CREATE, params, cb)
end

-- 打开配置中心页面
local function open_pay_center_webview(url, pay_params, error_params, cb)
    local pay_finished = false

    local last_pay_status
    local on_js_callback = function(_value)
        local args = _value.args
        E.LOG.debug(TAG, "open_pay_center_webview js callback >>")
        E.LOG.debug(TAG, args)

        --[[ 返回示例：
            {
               ["params"] => table: 0C13CFB8{
                  ["msg"] => "初始"
                  ["serverCode"] => 200000
                  ["orderStatus"] => -0
               }
               ["type"] => "win_pay_center_pay_result"
            }
            --]]
        if args.type == 'win_pay_center_pay_result' then
            E.LOG.debug(TAG, "open_pay_center_webview js callback, receive win_pay_center_pay_result >>")
            E.LOG.debug(TAG, args.params)

            -- 缓存支付状态
            last_pay_status = args.params or {}

            pay_finished = true
        end
    end

    local on_close_callback = function()
        if pay_finished then
            E.LOG.debug(TAG, "pay finished and webview is closed")

            -- check pay result
            last_pay_status = last_pay_status or {}
            local orderStatus = last_pay_status.orderStatus
            if orderStatus == H5_PAY_STATE.SUCCESS then
                E.LOG.debug(TAG, "receive pay succ")
                cb(true)
            else
                local msg = last_pay_status.msg
                local code = last_pay_status.serverCode
                E.LOG.warn(TAG, "receive pay failed, code:" .. tostring(code) .. ", msg:" .. tostring(msg))
                cb(false, code, msg)
            end
        else
            E.LOG.warn(TAG, "pay cancelled")
            cb(false, CONSTANTS.OFFICIAL_ERR_CODES.CODE_PAY_CANCEL, "pay cancelled")
        end
    end

    local start_up_data = {
        product_info = pay_params or {},
        cp_order_id = pay_params and pay_params.cpOrderId, -- 跟安卓的虚拟支付协议对齐
        order_amount = pay_params and tonumber(pay_params.amount)/100,-- 虚拟支付给前端除以100，单位换算成元
        product_name = pay_params and pay_params.payProductName,
        pay_error_data = error_params
    }
    E.LOG.debug(TAG, "open_pay_center_webview begin, url:" .. tostring(url) .. ", startup data >>")
    E.LOG.debug(TAG, start_up_data)

    local options = {
        hide_close_btn = true,
        min_width = 450,
        min_height = 400
    }
    E.open_webview_with_options(url, URL_WHITE_HOSTS, start_up_data, options, on_js_callback, on_close_callback)
end

