local function gen_failed_ext_params(_code, _msg)
    return {
        code = _code,
        msg = _msg
    }
end

local function do_pay(ejoy_order_id, pay_params, cb)
    -- 2、大圣接口下单, 接口文档：https://yuque.antfin-inc.com/ejoy-platform/ejoy-platform/hadm8b
    create_order(ejoy_order_id, pay_params, function(succ, ...)
        if succ then
            local data = ...
            -- 3、解析url，调用open_webview
            E.LOG.debug(TAG, "create_order result >>")
            E.LOG.debug(TAG, data)
            data = data or {}
            local ds_order_id = data.dsOrderId
            local pay_url = data.callbackUrl

            --pay_url = "http://30.211.153.83:7001/payCenter"
            --pay_url = 'https://daily-shop-lingxigames.alibaba.net/payCenter/resultMsg'
            pay_params = pay_params or {}
            pay_params.cpOrderId = ds_order_id
            if pay_url and pay_url ~= '' then
                E.LOG.debug(TAG, "open_pay_center_webview with url:" .. tostring(pay_url))
                open_pay_center_webview(pay_url, pay_params,nil, function(_succ, ...)
                    if _succ then
                        E.LOG.debug(TAG, "open_pay_center_webview received succ, now begin query pay result")
                        cb(true)
                    else
                        local code, msg = ...
                        E.LOG.warn(TAG, "open_pay_center_webview received failed, code:" .. tostring(code) .. ", msg:" .. tostring(msg))
                        cb(false, code, msg)
                    end
                end)
            else
                E.LOG.error(TAG, "pay failed, for pay url invalid")
                cb(false, CONSTANTS.CHANNEL_ERROR_CODE.CHANNEL_WIN_PAY_PAGE_INVALID, "支付页面地址无效")
            end

        else
            local code, msg, data = ...
            E.LOG.warn(TAG, 'create_order failed, code:' .. tostring(code) .. ', msg:' .. tostring(msg) .. ', data >>')
            E.LOG.debug(TAG, data)

            -- 针对错误码：5009010、5009011、5009012，同样需要打开webview，把错误信息通过start_up_data带给前端
            -- 为了方便后续扩展，只要服务器额外返回callbackUrl，就打开webview
            --code >= 5001010 and code <= 5009012 and
            if data and data.callbackUrl then
                local pay_url = data.callbackUrl
                -- 把code和msg也返回给js
                data.code = code
                data.msg = msg
                open_pay_center_webview(pay_url, pay_params, data, function(_succ, ...)
                    if _succ then
                        E.LOG.debug(TAG, " callbackUrl has data,open_pay_center_webview received succ, now begin query pay result")
                        cb(true)
                    else
                        local code2, msg2 = ...
                        E.LOG.warn(TAG, " callbackUrl has data,open_pay_center_webview received failed, code:" .. tostring(code2) .. ", msg:" .. tostring(msg2))
                        cb(false, code2, msg2)
                    end
                end)
            else
                cb(false, code, msg)

            end
        end
    end)
end

-- 支持主动调用的方式
function M.uni_pay(ejoy_order_id, pay_params, cb)
    E.LOG.debug(TAG, "uni pay begin")

    do_pay(ejoy_order_id, pay_params, function(succ, ...)
        -- 按照unisdk 的结果格式化输出
        if succ then
            cb(true, ejoy_order_id, {})
        else
            local code, msg = ...
            cb(false, ejoy_order_id, gen_failed_ext_params(code, msg))
        end
    end)
end

function M:is_support_ability(types)
    local is_support = check_platform_support()
    if not is_support then
        return false
    end

    -- call super
    return Vendor:is_support_ability(types)
end

